name:
[[[
  var cover = states[variables.entity_cover];
  var pos = (cover && cover.attributes && cover.attributes.current_position !== undefined) ? cover.attributes.current_position + '%' : '';
  return variables.friendly_name + (pos ? ' • ' + pos : '');
]]]

label:
[[[
  var s_auto = states[variables.entity_modus];
  var s_besch = states[variables.entity_beschattung];
  var o_auto = states[variables.entity_override_auto];
  var o_besch = states[variables.entity_override_besch];

  var is_auto = s_auto && s_auto.state === 'Manuell';
  var is_besch = s_besch && s_besch.state === 'Manuell';

  if (!is_auto && !is_besch) return 'Vollautomatik';

  var status = [];
  if (is_auto) {
    status.push(o_auto && o_auto.state === 'on' ? 'Auto AUS (Lokal)' : 'Auto AUS (Global)');
  }
  if (is_besch) {
    status.push(o_besch && o_besch.state === 'on' ? 'Beschattung AUS (Lokal)' : 'Beschattung AUS (Global)');
  }
  return status.join(' & ');
]]]

card.border:
[[[
  var s_auto = states[variables.entity_modus];
  var s_besch = states[variables.entity_beschattung];
  var any = (s_auto && s_auto.state === 'Manuell') || (s_besch && s_besch.state === 'Manuell');
  return !any ? '2px solid red' : '1px solid var(--ha-card-border-color, var(--divider-color))';
]]]

img_cell.background-color:
[[[
  var s_auto = states[variables.entity_modus];
  var s_besch = states[variables.entity_beschattung];
  var any = (s_auto && s_auto.state === 'Manuell') || (s_besch && s_besch.state === 'Manuell');
  if (!any) return 'rgba(244, 67, 54, 0.1)';
  var cover = states[variables.entity_cover];
  return (cover && cover.state === 'closed') ? 'rgba(150, 150, 150, 0.1)' : 'rgba(33, 150, 243, 0.15)';
]]]

icon.color:
[[[
  var s_auto = states[variables.entity_modus];
  var s_besch = states[variables.entity_beschattung];
  var any = (s_auto && s_auto.state === 'Manuell') || (s_besch && s_besch.state === 'Manuell');
  if (!any) return 'var(--error-color, #f44336)';
  var cover = states[variables.entity_cover];
  return (cover && cover.state === 'closed') ? 'var(--disabled-text-color)' : 'var(--accent-color, #2196f3)';
]]]

buttons.opacity:
[[[
